-- Fixture schema for pgmcp tests.
--
-- Deliberately exercises the awkward corners of the PostgreSQL catalog:
-- multiple schemas, composite and self-referencing foreign keys, partitioning,
-- inheritance, generated and identity columns, enums, domains, composite types,
-- ranges, arrays, jsonb, row-level security, triggers, materialised views,
-- expression and partial indexes, a deliberately unused index, a duplicate
-- index, and identifiers that need quoting.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

DROP SCHEMA IF EXISTS shop CASCADE;
DROP SCHEMA IF EXISTS analytics CASCADE;
DROP SCHEMA IF EXISTS "Odd Schema" CASCADE;

CREATE SCHEMA shop;
CREATE SCHEMA analytics;
CREATE SCHEMA "Odd Schema";

COMMENT ON SCHEMA shop IS 'Transactional storefront data.';

-- ---------------------------------------------------------------- types ----
CREATE TYPE shop.order_status AS ENUM ('pending', 'paid', 'shipped', 'cancelled');
CREATE TYPE shop.address AS (line1 text, city text, postcode text);
CREATE DOMAIN shop.email AS text CHECK (VALUE ~ '^[^@]+@[^@]+$');

-- --------------------------------------------------------------- tables ----
CREATE TABLE shop.customers (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email       shop.email NOT NULL UNIQUE,
    full_name   text NOT NULL,
    referred_by bigint REFERENCES shop.customers (id) ON DELETE SET NULL,
    billing     shop.address,
    tags        text[] DEFAULT '{}',
    metadata    jsonb NOT NULL DEFAULT '{}'::jsonb,
    lifetime_ms bigint,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT customers_name_not_blank CHECK (length(btrim(full_name)) > 0)
);

COMMENT ON TABLE shop.customers IS 'One row per registered customer.';
COMMENT ON COLUMN shop.customers.referred_by IS 'Self-referencing referral link.';

CREATE TABLE shop.products (
    sku         text PRIMARY KEY,
    name        text NOT NULL,
    price_cents integer NOT NULL CHECK (price_cents >= 0),
    price_eur   numeric(12, 2) GENERATED ALWAYS AS (price_cents / 100.0) STORED,
    in_stock    boolean NOT NULL DEFAULT true,
    valid_for   daterange
);

CREATE TABLE shop.orders (
    id           bigserial PRIMARY KEY,
    customer_id  bigint NOT NULL REFERENCES shop.customers (id) ON DELETE CASCADE,
    status       shop.order_status NOT NULL DEFAULT 'pending',
    total_cents  integer NOT NULL DEFAULT 0,
    placed_at    timestamptz NOT NULL DEFAULT now()
);

-- Composite primary key plus a composite foreign key.
CREATE TABLE shop.order_items (
    order_id   bigint NOT NULL REFERENCES shop.orders (id) ON DELETE CASCADE,
    line_no    integer NOT NULL,
    sku        text NOT NULL REFERENCES shop.products (sku),
    quantity   integer NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, line_no)
);

-- Range-partitioned table with two partitions.
CREATE TABLE shop.events (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    occurred_at date NOT NULL,
    kind       text NOT NULL,
    payload    jsonb,
    PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);

CREATE TABLE shop.events_2023 PARTITION OF shop.events
    FOR VALUES FROM ('2023-01-01') TO ('2024-01-01');
CREATE TABLE shop.events_2024 PARTITION OF shop.events
    FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');

-- Table inheritance (distinct from partitioning).
CREATE TABLE shop.base_audit (id bigserial PRIMARY KEY, at timestamptz DEFAULT now());
CREATE TABLE shop.child_audit (detail text) INHERITS (shop.base_audit);

-- An identifier that must be quoted everywhere it appears.
CREATE TABLE "Odd Schema"."Weird Table" (
    "Id Column" integer PRIMARY KEY,
    "select"    text,
    "a""b"      text
);

-- -------------------------------------------------------------- indexes ----
CREATE INDEX orders_customer_idx        ON shop.orders (customer_id);
CREATE INDEX orders_customer_dup_idx    ON shop.orders (customer_id);            -- duplicate
CREATE INDEX orders_placed_at_idx       ON shop.orders (placed_at DESC);
CREATE INDEX orders_pending_idx         ON shop.orders (customer_id) WHERE status = 'pending';
CREATE INDEX customers_lower_email_idx  ON shop.customers (lower(email::text));  -- expression
CREATE INDEX customers_tags_gin         ON shop.customers USING gin (tags);
CREATE INDEX customers_never_used_idx   ON shop.customers (lifetime_ms);         -- unused

-- ---------------------------------------------------------------- views ----
CREATE VIEW shop.active_orders AS
    SELECT o.id, o.customer_id, c.email, o.status, o.total_cents
    FROM shop.orders o
    JOIN shop.customers c ON c.id = o.customer_id
    WHERE o.status <> 'cancelled';

COMMENT ON VIEW shop.active_orders IS 'Orders that have not been cancelled.';

CREATE MATERIALIZED VIEW analytics.revenue_by_status AS
    SELECT status, count(*) AS orders, sum(total_cents) AS revenue_cents
    FROM shop.orders
    GROUP BY status;

CREATE UNIQUE INDEX revenue_by_status_pk ON analytics.revenue_by_status (status);

-- ------------------------------------------------------------ functions ----
CREATE FUNCTION shop.order_total(p_order_id bigint)
RETURNS integer
LANGUAGE sql
STABLE
AS $$
    SELECT COALESCE(sum(p.price_cents * i.quantity), 0)::integer
    FROM shop.order_items i
    JOIN shop.products p ON p.sku = i.sku
    WHERE i.order_id = p_order_id;
$$;

COMMENT ON FUNCTION shop.order_total(bigint) IS 'Sum of line items for an order, in cents.';

CREATE FUNCTION shop.touch_order() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.total_cents := shop.order_total(NEW.id);
    RETURN NEW;
END;
$$;

CREATE TRIGGER orders_touch
    BEFORE UPDATE ON shop.orders
    FOR EACH ROW EXECUTE FUNCTION shop.touch_order();

CREATE PROCEDURE shop.cancel_order(p_order_id bigint)
LANGUAGE sql AS $$
    UPDATE shop.orders SET status = 'cancelled' WHERE id = p_order_id;
$$;

-- ---------------------------------------------------------- row security ----
CREATE TABLE shop.tenant_notes (
    id        bigserial PRIMARY KEY,
    tenant_id text NOT NULL,
    body      text NOT NULL
);
ALTER TABLE shop.tenant_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON shop.tenant_notes
    USING (tenant_id = current_setting('app.tenant', true));

-- --------------------------------------------------------------- data ------
INSERT INTO shop.customers (email, full_name, tags, metadata, lifetime_ms)
SELECT
    'user' || g || '@example.com',
    'Customer ' || g,
    ARRAY['tier' || (g % 3)],
    jsonb_build_object('signup_source', CASE WHEN g % 2 = 0 THEN 'web' ELSE 'mobile' END),
    g * 1000
FROM generate_series(1, 200) g;

UPDATE shop.customers SET referred_by = 1 WHERE id BETWEEN 2 AND 20;

INSERT INTO shop.products (sku, name, price_cents, in_stock)
SELECT 'SKU-' || lpad(g::text, 4, '0'), 'Product ' || g, g * 250, g % 7 <> 0
FROM generate_series(1, 60) g;

INSERT INTO shop.orders (customer_id, status, total_cents, placed_at)
SELECT
    1 + (g % 200),
    (ARRAY['pending', 'paid', 'shipped', 'cancelled'])[1 + (g % 4)]::shop.order_status,
    g * 100,
    now() - (g || ' hours')::interval
FROM generate_series(1, 500) g;

INSERT INTO shop.order_items (order_id, line_no, sku, quantity)
SELECT 1 + (g % 500), 1 + (g / 500), 'SKU-' || lpad((1 + (g % 60))::text, 4, '0'), 1 + (g % 5)
FROM generate_series(0, 999) g;

INSERT INTO shop.events (occurred_at, kind, payload)
SELECT
    DATE '2023-01-01' + (g % 700),
    (ARRAY['view', 'click', 'purchase'])[1 + (g % 3)],
    jsonb_build_object('n', g)
FROM generate_series(1, 400) g;

INSERT INTO "Odd Schema"."Weird Table" VALUES (1, 'reserved word column', 'quoted');
INSERT INTO shop.tenant_notes (tenant_id, body) VALUES ('acme', 'hello'), ('globex', 'world');

REFRESH MATERIALIZED VIEW analytics.revenue_by_status;
ANALYZE;
